import{_ as d,a0 as p,w as o,s as u,I as e,x as n,a1 as t,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 使用 systemd-udevd 管理你的接入硬件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20200204 Managing your attached hardware on Linux with systemd-udevd","title":"在 Linux 使用 systemd-udevd 管理你的接入硬件","tag":"202108","desc":""},"relativePath":"202108/20200204 Managing your attached hardware on Linux with systemd-udevd.md","filePath":"[post].md"}'),r={name:"202108/20200204 Managing your attached hardware on Linux with systemd-udevd.md"};function g(f,s,b,c,k,m){const a=p("Link");return o(),u("div",null,[s[38]||(s[38]=e("h1",{id:"在-linux-使用-systemd-udevd-管理你的接入硬件",tabindex:"-1"},[n("在 Linux 使用 systemd-udevd 管理你的接入硬件 "),e("a",{class:"header-anchor",href:"#在-linux-使用-systemd-udevd-管理你的接入硬件","aria-label":"Permalink to “在 Linux 使用 systemd-udevd 管理你的接入硬件”"},"​")],-1)),s[39]||(s[39]=e("blockquote",null,[e("p",null,"使用 udev 管理你的 Linux 系統處理物理設備的方式。")],-1)),s[40]||(s[40]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/17/104654z1evcdx41xfc4zpq.jpg",alt:""})],-1)),s[41]||(s[41]=e("p",null,"Linux 能夠出色地自動識別、加載、並公開接入的無數廠商的硬件設備。事實上，很多年以前，正是這個特性説服我，堅持讓我的僱主將整個基礎設施轉換到 Linux。痛點在於 Redmond 的某家公司（LCTT 譯註：指微軟）不能在我們的 Compaq 台式機上加載集成網卡的驅動，而 Linux 可以輕鬆實現這一點。",-1)),e("p",null,[s[1]||(s[1]=n("從那以後的歲月裏，Linux 的識別設備庫隨着該過程的複雜化而與日俱增，而 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Udev"},{default:i(()=>[...s[0]||(s[0]=[n("udev",-1)])]),_:1}),s[2]||(s[2]=n(" 就是解決這個問題的希望之星。udev 負責監聽 Linux 內核發出的改變設備狀態的事件。它可能是一個新 USB 設備被插入或拔出，也可能是一個無線鼠標因浸入灑出的咖啡中而脱機。",-1))]),e("p",null,[s[4]||(s[4]=n("udev 負責處理所有的狀態變更，比如指定訪問設備使用的名稱和權限。這些更改的記錄可以通過 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Dmesg"},{default:i(()=>[...s[3]||(s[3]=[n("dmesg",-1)])]),_:1}),s[5]||(s[5]=n(" 獲取。由於 dmesg 的輸出通常有幾千行，對結果進行過濾通常是聰明的選擇。下面的例子説明了 Linux 如何識別我的 WiFi 接口。這個例子展示了我的無線設備使用的芯片組（",-1)),s[6]||(s[6]=e("code",null,"ath9k",-1)),s[7]||(s[7]=n("）、啓動過程早期階段分配的原始名稱（",-1)),s[8]||(s[8]=e("code",null,"wlan0",-1)),s[9]||(s[9]=n("）、以及正在使用的又臭又長的永久名稱（",-1)),s[10]||(s[10]=e("code",null,"wlxec086b1ef0b3",-1)),s[11]||(s[11]=n("）：",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dmesg | grep wlan</span></span>
<span class="line"><span>[    5.396874] ath9k_htc 1-3:1.0 wlxec086b1ef0b3: renamed from wlan0</span></span></code></pre></div>`,1)),e("p",null,[s[13]||(s[13]=n("在這篇文章中，我會討論為何有人想要使用這樣的名稱。在這個過程中，我會探索剖析 udev 的配置文件，然後展示如何更改 udev 的設置，包括編輯系統命名設備的方式。這篇文件基於我的新課程中《",-1)),t(a,{href:"https://pluralsight.pxf.io/RqrJb"},{default:i(()=>[...s[12]||(s[12]=[n("Linux 系統優化",-1)])]),_:1}),s[14]||(s[14]=n("》的一個模組。",-1))]),s[43]||(s[43]=l(`<h3 id="理解-udev-配置系統" tabindex="-1">理解 udev 配置系統 <a class="header-anchor" href="#理解-udev-配置系統" aria-label="Permalink to “理解 udev 配置系統”">​</a></h3><p>使用 systemd 的機器上，udev 操作由 <code>systemd-udevd</code> 守護進程管理，你可以通過常規的 systemd 方式使用 <code>systemctl status systemd-udevd</code> 檢查 udev 守護進程的狀態。</p><p>嚴格來説，udev 的工作方式是試圖將它收到的每個系統事件與 <code>/lib/udev/rules.d/</code> 和 <code>/etc/udev/rules.d/</code> 目錄下找到的規則集進行匹配。規則文件包括匹配鍵和分配鍵，可用的匹配鍵包括 <code>action</code>、<code>name</code> 和 <code>subsystem</code>。這意味着如果探測到一個屬於某個子系統的、帶有特定名稱的設備，就會給設備指定一個預設的配置。</p><p>接着，“分配”鍵值對被拿來應用想要的配置。例如，你可以給設備分配一個新名稱、將其關聯到文件系統中的一個符號鏈接、或者限制為只能由特定的所有者或組訪問。這是從我的工作站摘出的一條規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /lib/udev/rules.d/73-usb-net-by-mac.rules</span></span>
<span class="line"><span># Use MAC based names for network interfaces which are directly or indirectly</span></span>
<span class="line"><span># on USB and have an universally administered (stable) MAC address (second bit</span></span>
<span class="line"><span># is 0). Don&#39;t do this when ifnames is disabled via kernel command line or</span></span>
<span class="line"><span># customizing/disabling 99-default.link (or previously 80-net-setup-link.rules).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>IMPORT{cmdline}=&quot;net.ifnames&quot;</span></span>
<span class="line"><span>ENV{net.ifnames}==&quot;0&quot;, GOTO=&quot;usb_net_by_mac_end&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;net&quot;, SUBSYSTEMS==&quot;usb&quot;, NAME==&quot;&quot;, \\</span></span>
<span class="line"><span>    ATTR{address}==&quot;?[014589cd]:*&quot;, \\</span></span>
<span class="line"><span>    TEST!=&quot;/etc/udev/rules.d/80-net-setup-link.rules&quot;, \\</span></span>
<span class="line"><span>    TEST!=&quot;/etc/systemd/network/99-default.link&quot;, \\</span></span>
<span class="line"><span>    IMPORT{builtin}=&quot;net_id&quot;, NAME=&quot;$env{ID_NET_NAME_MAC}&quot;</span></span></code></pre></div><p><code>add</code> 動作告訴 udev，只要新插入的設備屬於網絡子系統，<em>並且</em>是一個 USB 設備，就執行操作。此外，如果我理解正確的話，只有設備的 MAC 地址由特定範圍內的字符組成，並且 <code>80-net-setup-link.rules</code> 和 <code>99-default.link</code> 文件<em>不</em>存在時，規則才會生效。</p><p>假定所有的條件都滿足，接口 ID 會改變以匹配設備的 MAC 地址。還記得之前的 dmesg 信息顯示我的接口名稱從 <code>wlan0</code> 改成了討厭的 <code>wlxec086b1ef0b3</code> 嗎？那都是這條規則的功勞。我怎麼知道？因為 <code>ec:08:6b:1e:f0:b3</code> 是設備的 MAC 地址（不包括冒號）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig -a</span></span>
<span class="line"><span>wlxec086b1ef0b3: flags=4163&lt;UP,BROADCAST,RUNNING,MULTICAST&gt;  mtu 1500</span></span>
<span class="line"><span>        inet 192.168.0.103  netmask 255.255.255.0  broadcast 192.168.0.255</span></span>
<span class="line"><span>        inet6 fe80::7484:3120:c6a3:e3d1  prefixlen 64  scopeid 0x20&lt;link&gt;</span></span>
<span class="line"><span>        ether ec:08:6b:1e:f0:b3  txqueuelen 1000  (Ethernet)</span></span>
<span class="line"><span>        RX packets 682098  bytes 714517869 (714.5 MB)</span></span>
<span class="line"><span>        RX errors 0  dropped 0  overruns 0  frame 0</span></span>
<span class="line"><span>        TX packets 472448  bytes 201773965 (201.7 MB)</span></span>
<span class="line"><span>        TX errors 0  dropped 0 overruns 0  carrier 0  collisions 0</span></span></code></pre></div><p>Linux 默認包含這條 udev 規則，我不需要自己寫。但是為什麼費力進行這樣的命名呢——尤其是看到這樣的接口命名這麼難使用後？仔細看一下包含在規則中的註釋：</p><blockquote><p>對直接或間接插入在 USB 上的網絡接口使用基於 MAC 的名稱，並且用一個普遍提供的（穩定的）MAC 地址（第二位是 0）。當 ifnames 通過內核命令列或 <code>customizing/disabling 99-default.link</code>（或之前的 <code>80-net-setup-link.rules</code>）被禁用時，不要這樣做。</p></blockquote><p>注意，這個規則專為基於 USB 的網絡接口設計的。和 PCI 網絡接口卡（NIC）不同，USB 設備很可能時不時地被移除或者替換，這意味着無法保證它們的 ID 不變。某一天 ID 可能是 <code>wlan0</code>，第二天卻變成了 <code>wlan3</code>。為了避免迷惑應用程序，指定絕對 ID 給設備——就像分配給我的 USB 接口的 ID。</p><h3 id="操作-udev-的設置" tabindex="-1">操作 udev 的設置 <a class="header-anchor" href="#操作-udev-的設置" aria-label="Permalink to “操作 udev 的設置”">​</a></h3>`,12)),e("p",null,[s[16]||(s[16]=n("下一個示例中，我將從 ",-1)),t(a,{href:"https://www.virtualbox.org/"},{default:i(()=>[...s[15]||(s[15]=[n("VirtualBox",-1)])]),_:1}),s[17]||(s[17]=n(" 虛擬機裏抓取以太網接口的 MAC 地址和當前接口 ID，然後用這些信息創建一個改變接口 ID 的 udev 新規則。為什麼這麼做？也許我打算從命令列操作設備，需要輸入那麼長的名稱讓人十分煩惱。下面是工作原理。",-1))]),e("p",null,[s[19]||(s[19]=n("改變接口 ID 之前，我需要關閉 ",-1)),t(a,{href:"https://netplan.io/"},{default:i(()=>[...s[18]||(s[18]=[n("Netplan",-1)])]),_:1}),s[20]||(s[20]=n(" 當前的網絡配置，促使 Linux 使用新的配置。下面是 ",-1)),s[21]||(s[21]=e("code",null,"/etc/netplan/",-1)),s[22]||(s[22]=n(" 目錄下我的當前網絡接口配置文件：",-1))]),s[44]||(s[44]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less /etc/netplan/50-cloud-init.yaml</span></span>
<span class="line"><span># This file is generated from information provided by</span></span>
<span class="line"><span># the datasource.  Changes to it will not persist across an instance.</span></span>
<span class="line"><span># To disable cloud-init&#39;s network configuration capabilities, write a file</span></span>
<span class="line"><span># /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg with the following:</span></span>
<span class="line"><span># network: {config: disabled}</span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>        enp0s3:</span></span>
<span class="line"><span>            addresses: []</span></span>
<span class="line"><span>            dhcp4: true</span></span>
<span class="line"><span>    version: 2</span></span></code></pre></div><p><code>50-cloud-init.yaml</code> 文件包含一個非常基本的接口定義，但是註釋中也包含一些禁用配置的重要信息。為此，我將移動到 <code>/etc/cloud/cloud.cfg.d</code> 目錄，創建一個名為 <code>/etc/cloud/cloud.cfg.d</code> 的新文件，插入 <code>network: {config: disabled}</code> 字符串。</p><p>儘管我只在 Ubuntu 發行版上測試了這個方法，但它應該在任何一個帶有 systemd 的 Linux（幾乎所有的 Linux 發行版都有 systemd）上都可以工作。不管你使用哪個，都可以很好地瞭解編寫 udev 配置文件並對其進行測試。</p><p>接下來，我需要收集一些系統信息。執行 <code>ip</code> 命令，顯示我的以太網接口名為 <code>enp0s3</code>，MAC 地址是 <code>08:00:27:1d:28:10</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span>
<span class="line"><span>2: enp0s3: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc fq_codel state UP group default qlen 1000</span></span>
<span class="line"><span>    link/ether 08:00:27:1d:28:10 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>    inet 192.168.0.115/24 brd 192.168.0.255 scope global dynamic enp0s3</span></span></code></pre></div><p>現在，我要在 <code>/etc/udev/rules.d</code> 目錄創建一個名為 <code>peristent-net.rules</code> 的新文件。我將給文件一個以較小的數字開頭的名稱，比如 10：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/udev/rules.d/10-persistent-network.rules</span></span>
<span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;net&quot;,ATTR{address}==&quot;08:00:27:1d:28:10&quot;,NAME=&quot;eth3&quot;</span></span></code></pre></div><p>數字越小，Linux 越早執行文件，我想要這個文件早點執行。文件被添加時，包含其中的代碼就會分配名稱 <code>eth3</code> 給網絡設備——只要設備的地址能夠匹配 <code>08:00:27:1d:28:10</code>，即我的接口的 MAC 地址 。</p><p>保存文件並重啓計算機後，我的新接口名應該就會生效。我可能需要直接登錄虛擬機，使用 <code>dhclient</code> 手動讓 Linux 為這個新命名的網絡請求一個 IP 地址。在執行下列命令前，可能無法打開 SSH 會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dhclient eth3</span></span></code></pre></div><p>大功告成。現在你能夠促使 udev 控制計算機按照你想要的方式指向一個網卡，但更重要的是，你已經有了一些工具，可以弄清楚如何管理任何不聽話的設備。</p><hr>`,12)),e("p",null,[s[24]||(s[24]=n("via: ",-1)),t(a,{href:"https://opensource.com/article/20/2/linux-systemd-udevd"},{default:i(()=>[...s[23]||(s[23]=[n("https://opensource.com/article/20/2/linux-systemd-udevd",-1)])]),_:1})]),e("p",null,[s[29]||(s[29]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/dbclinton"},{default:i(()=>[...s[25]||(s[25]=[n("David Clinton",-1)])]),_:1}),s[30]||(s[30]=n(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[n("lujun9972",-1)])]),_:1}),s[31]||(s[31]=n(" 譯者：",-1)),t(a,{href:"https://github.com/YungeG"},{default:i(()=>[...s[27]||(s[27]=[n("YungeG",-1)])]),_:1}),s[32]||(s[32]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[35]||(s[35]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[n("LCTT",-1)])]),_:1}),s[36]||(s[36]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[n("Linux中國",-1)])]),_:1}),s[37]||(s[37]=n(" 榮譽推出",-1))])])}const T=d(r,[["render",g]]);export{x as __pageData,T as default};
